<?php
declare(strict_types=1);
namespace App\Application\Auth\RegisterUser;
use App\Application\Auth\Security\PasswordHasher;use App\Application\Shared\TransactionManager;use App\Domain\Audit\AuditLog;use App\Domain\Audit\AuditLogRepository;use App\Domain\Auth\User\Email;use App\Domain\Auth\User\PasswordHash;use App\Domain\Auth\User\PasswordTooShort;use App\Domain\Auth\User\User;use App\Domain\Auth\User\UserAlreadyExists;use App\Domain\Auth\User\UserRepository;
final class RegisterUserHandler { public function __construct(private UserRepository $users, private PasswordHasher $hasher, private TransactionManager $tx, private AuditLogRepository $audit) {} public function handle(RegisterUserCommand $command): RegisterUserResult { if (mb_strlen($command->plainPassword) < 10) { throw new PasswordTooShort('Password must be at least 10 characters'); } return $this->tx->transactional(function () use ($command): RegisterUserResult { $email = Email::fromString($command->email); if ($this->users->byEmail($email) !== null) { throw new UserAlreadyExists('Email already exists'); } $user = User::register($this->users->nextId(), $email, PasswordHash::fromHash($this->hasher->hash($command->plainPassword))); $this->users->save($user); foreach ($user->releaseDomainEvents() as $event) { $this->audit->save(AuditLog::fromDomainEvent($event)); } return new RegisterUserResult($user->id()->value(), $user->email()->value()); }); }}
